-- PSP controls for a merchant (1:1 with the legacy merchants row): verification, risk class, fund policy, suspension.
CREATE TABLE psp_merchant_profiles (
    id                           BIGINT AUTO_INCREMENT PRIMARY KEY,
    merchant_id                  BIGINT NOT NULL,
    merchant_type                VARCHAR(20) NOT NULL DEFAULT 'MERCHANT',
    parent_merchant_id           BIGINT,
    verification_status          VARCHAR(20) NOT NULL,
    verified_by                  VARCHAR(120),
    verified_at                  DATETIME(6),
    kyc_review_due_at            DATETIME(6),
    risk_class                   VARCHAR(20) NOT NULL,
    risk_reason                  VARCHAR(500),
    mcc                          VARCHAR(4),
    hold_days                    INT NOT NULL DEFAULT 0,
    reserve_bps                  INT NOT NULL DEFAULT 0,
    reserve_days                 INT NOT NULL DEFAULT 0,
    settlement_frequency         VARCHAR(20) NOT NULL DEFAULT 'DAILY',
    min_payout_minor             BIGINT NOT NULL DEFAULT 0,
    suspension_scope             VARCHAR(20) NOT NULL DEFAULT 'NONE',
    suspension_reason            VARCHAR(500),
    suspended_by                 VARCHAR(120),
    suspended_at                 DATETIME(6),
    created_at                   DATETIME(6) NOT NULL,
    updated_at                   DATETIME(6) NOT NULL,
    version                      BIGINT NOT NULL DEFAULT 0,
    CONSTRAINT uq_merchant_profiles_merchant_id UNIQUE (merchant_id),
    INDEX idx_mprof_verification (verification_status)
);

-- A payment method / currency a merchant is approved to accept. Nothing is collectable unless approved here.
CREATE TABLE psp_merchant_products (
    id                           BIGINT AUTO_INCREMENT PRIMARY KEY,
    merchant_id                  BIGINT NOT NULL,
    payment_method_code          VARCHAR(50) NOT NULL,
    currency                     VARCHAR(3) NOT NULL,
    status                       VARCHAR(20) NOT NULL,
    approved_by                  VARCHAR(120),
    approved_at                  DATETIME(6),
    created_at                   DATETIME(6) NOT NULL,
    updated_at                   DATETIME(6) NOT NULL,
    CONSTRAINT uq_mprod UNIQUE (merchant_id,payment_method_code,currency)
);

-- Per-merchant transaction limits by currency. PER_TXN_MIN, PER_TXN_MAX, DAILY_AMOUNT, MONTHLY_AMOUNT, DAILY_COUNT.
CREATE TABLE psp_merchant_limits (
    id                           BIGINT AUTO_INCREMENT PRIMARY KEY,
    merchant_id                  BIGINT NOT NULL,
    currency                     VARCHAR(3) NOT NULL,
    limit_type                   VARCHAR(20) NOT NULL,
    limit_value                  BIGINT NOT NULL DEFAULT 0,
    approved_by                  VARCHAR(120),
    created_at                   DATETIME(6) NOT NULL,
    updated_at                   DATETIME(6) NOT NULL,
    CONSTRAINT uq_mlimit UNIQUE (merchant_id,currency,limit_type)
);

-- Where a merchant's settlements are paid. Encrypted at rest; changes need four-eyes verification and a cooling-off period.
CREATE TABLE psp_merchant_payout_accounts (
    id                           BIGINT AUTO_INCREMENT PRIMARY KEY,
    payout_ref                   VARCHAR(40) NOT NULL,
    merchant_id                  BIGINT NOT NULL,
    currency                     VARCHAR(3) NOT NULL,
    method                       VARCHAR(20) NOT NULL,
    bank_name                    VARCHAR(120),
    bank_code                    VARCHAR(40),
    branch_code                  VARCHAR(40),
    account_name                 VARCHAR(200) NOT NULL,
    account_number               VARCHAR(600),
    account_number_last4         VARCHAR(4),
    mobile_number                VARCHAR(600),
    status                       VARCHAR(30) NOT NULL,
    created_by                   VARCHAR(120) NOT NULL,
    verified_by                  VARCHAR(120),
    verified_at                  DATETIME(6),
    cooling_off_until            DATETIME(6),
    created_at                   DATETIME(6) NOT NULL,
    updated_at                   DATETIME(6) NOT NULL,
    CONSTRAINT uq_merchant_payout_accounts_payout_ref UNIQUE (payout_ref),
    INDEX idx_mpayout_merchant (merchant_id,currency,status)
);

-- Commercial terms. merchantId null = platform default; paymentMethodCode null = any method. Activated via four-eyes approval.
CREATE TABLE psp_fee_agreements (
    id                           BIGINT AUTO_INCREMENT PRIMARY KEY,
    agreement_ref                VARCHAR(40) NOT NULL,
    merchant_id                  BIGINT,
    payment_method_code          VARCHAR(50),
    currency                     VARCHAR(3) NOT NULL,
    percent_bps                  INT NOT NULL DEFAULT 0,
    fixed_minor                  BIGINT NOT NULL DEFAULT 0,
    min_fee_minor                BIGINT NOT NULL DEFAULT 0,
    max_fee_minor                BIGINT NOT NULL DEFAULT 0,
    effective_from               DATETIME(6) NOT NULL,
    effective_to                 DATETIME(6),
    status                       VARCHAR(20) NOT NULL,
    created_by                   VARCHAR(120) NOT NULL,
    approved_by                  VARCHAR(120),
    notes                        VARCHAR(500),
    created_at                   DATETIME(6) NOT NULL,
    updated_at                   DATETIME(6) NOT NULL,
    CONSTRAINT uq_fee_agreements_agreement_ref UNIQUE (agreement_ref),
    INDEX idx_fee_lookup (merchant_id,currency,status)
);

-- Tax rates set by finance (VAT on fees, IMTT). Never hard-coded: rates change with the Finance Act.
CREATE TABLE psp_tax_rates (
    id                           BIGINT AUTO_INCREMENT PRIMARY KEY,
    tax_code                     VARCHAR(20) NOT NULL,
    currency                     VARCHAR(3) NOT NULL,
    rate_bps                     INT NOT NULL DEFAULT 0,
    cap_minor                    BIGINT NOT NULL DEFAULT 0,
    threshold_minor              BIGINT NOT NULL DEFAULT 0,
    merchant_borne               BOOLEAN NOT NULL DEFAULT FALSE,
    effective_from               DATETIME(6) NOT NULL,
    effective_to                 DATETIME(6),
    status                       VARCHAR(20) NOT NULL,
    created_by                   VARCHAR(120) NOT NULL,
    approved_by                  VARCHAR(120),
    notes                        VARCHAR(500),
    created_at                   DATETIME(6) NOT NULL,
    INDEX idx_tax_lookup (tax_code,currency,status)
);
